INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(31930787, 'Meklord Emperor Skiel', '机皇帝 神空∞', '機皇帝スキエル∞', 'Effect Monster', 'Machine', 'WIND', 1, 2200, 2200, '这张卡不能通常召唤，用自身的效果才能特殊召唤。 ①：自己场上的表侧表示怪兽被效果破坏送去墓地时才能发动。手卡的这张卡特殊召唤。 ②：1回合1次，以对方场上1只同调怪兽为对象才能发动。那只对方同调怪兽给这张卡装备。 ③：这个攻击力上升自身的效果装备的怪兽的攻击力数值，其他的自己怪兽不能攻击宣言。 ④：把给自身装备的1只自己怪兽送去墓地才能发动。这个回合这张卡可以直接攻击。'),
(68140974, 'Meklord Emperor Wisel', '机皇帝 神智∞', '機皇帝ワイゼル∞', 'Effect Monster', 'Machine', 'DARK', 1, 2500, 2500, '这张卡不能通常召唤，用自身的效果才能特殊召唤。 ①：自己场上的表侧表示怪兽被效果破坏送去墓地时才能发动。手卡的这张卡特殊召唤。 ②：1回合1次，以对方场上1只同调怪兽为对象才能发动。那只对方同调怪兽给这张卡装备。 ③：这个攻击力上升自身的效果装备的怪兽的攻击力数值，其他的自己怪兽不能攻击宣言。 ④：1回合1次，对方把魔法卡发动时才能发动。那个发动无效并破坏。'),
(30221870, 'Meklord Emperor Wisel - Synchro Absorption', '机皇帝 神智∞-同调吸收', '機皇帝ワイゼル∞－S・アブソープション', 'Effect Monster', 'Machine', 'DARK', 1, 2500, 2500, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：对方回合，把自己场上1只表侧表示的「机皇」怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。这个回合，那只怪兽不能攻击。 ③：要让场上的卡破坏的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。'),
(77864539, 'Meklord Factory', '机皇厂', '機皇廠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的名字带有「机皇」的怪兽被选择作为攻击对象时才能发动。选择自己墓地存在的1只名字带有「机皇兵」的怪兽加入手卡。那之后，成为攻击对象的怪兽破坏。'),
(67328336, 'Meklord Fortress', '机皇城', '機皇城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「机皇帝」怪兽不会成为同调怪兽的效果的对象。 ②：场上的这张卡被破坏送去墓地时才能发动。从卡组把1只「机皇帝」怪兽加入手卡。'),
(77710579, 'Meklord Nucleus Infinity Core', '机皇枢 无限核', '機皇枢インフィニティ・コア', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「机皇」魔法·陷阱卡加入手卡。 ②：这张卡1回合只有1次不会被战斗破坏。 ③：这张卡被效果破坏的场合才能发动。相同属性的怪兽不在自己场上存在的1只「机皇帝」怪兽从手卡·卡组无视召唤条件特殊召唤。这个效果的发动后，直到回合结束时自己只能用1只怪兽攻击宣言。'),
(41475424, 'Mektimed Blast', '机限爆弹', '機限爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「机皇」的怪兽和对方场上存在的1张卡发动。选择的卡破坏。'),
(86569121, 'Melchid the Four-Face Beast', '梅尔基多四面兽', 'メルキド四面獣', 'Normal Monster', 'Fiend', 'DARK', 4, 1500, 1200, '一边变换4张假面，一边发起4种攻击的怪物。'),
(93018428, 'Melffy Catty', '梅尔菲・凯西', 'メルフィー・キャシィ', 'Effect Monster', 'Beast', 'EARTH', 2, 200, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽召唤·特殊召唤的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到手卡。那之后，可以从卡组把「童话动物·小猫」以外的1只兽族怪兽加入手卡。 ②：自己结束阶段才能发动。这张卡从手卡特殊召唤。'),
(57523313, 'Melffy Fenny', '梅尔菲・芬尼', 'メルフィー・フェニィ', 'Effect Monster', 'Beast', 'EARTH', 2, 100, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：对方对怪兽的召唤·特殊召唤成功的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到持有者手卡。那之后，可以从手卡把「童话动物·小阔耳狐」以外的1只兽族怪兽特殊召唤。 ②：自己结束阶段才能发动。这张卡从手卡特殊召唤。'),
(63644830, 'Melffy Hide-and-Seek', '梅尔菲躲猫猫', 'メルフィーのかくれんぼ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的兽族怪兽在1回合各有1次不会被效果破坏。 ②：以自己墓地3只兽族怪兽为对象才能发动（同名卡最多1张）。那些怪兽回到卡组。那之后，自己抽1张。'),
(76833149, 'Melffy Mommy', '梅尔菲・玛咪', 'メルフィー・マミィ', 'XYZ Monster', 'Beast', 'EARTH', 2, 1000, 1000, '兽族2星怪兽×2只以上 ①：自己·对方回合1次，可以发动。从自己的手卡·场上选1只兽族怪兽在这张卡下面重叠作为超量素材。 ②：这张卡持有的超量素材数量让这张卡得到以下效果。 ●3个以上：这张卡不会被战斗破坏。 ●4个以上：这张卡的战斗发生的对自己的战斗伤害变成0。 ●5个以上：这张卡和攻击表示怪兽进行战斗的攻击宣言时才能发动。给与对方那只攻击表示怪兽的攻击力数值的伤害。'),
(30439101, 'Melffy of the Forest', '森林的梅尔菲们', '森のメルフィーズ', 'XYZ Monster', 'Beast', 'EARTH', 2, 500, 2000, '2星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「童话动物」卡加入手卡。 ②：自己场上的其他的表侧表示的「童话动物」怪兽回到自己手卡的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽只要在场上表侧表示存在，不能攻击，效果无效化。'),
(34800281, 'Melffy Pinny', '梅尔菲・乐西', 'メルフィー・ラッシィ', 'Tuner Monster', 'Beast', 'WATER', 2, 300, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：「童话动物·小海豹」以外的自己场上的表侧表示的兽族怪兽回到手卡的自己·对方回合才能发动。这张卡从手卡特殊召唤。那之后，可以只用这张卡和手卡的「童话动物」怪兽为素材进行同调召唤。 ②：自己结束阶段有这张卡在墓地存在的场合，以自己场上1只兽族超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(82134632, 'Melffy Playhouse', '梅尔菲过家家', 'メルフィータイム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上的兽族超量怪兽的超量素材任意数量取除，以最多有那个数量的对方场上的卡为对象才能发动。那些卡回到持有者手卡。自己场上的全部兽族超量怪兽的攻击力直到回合结束时上升因为这张卡发动而取除的超量素材数量×500。'),
(56401775, 'Melffy Pony', '梅尔菲・波尼', 'メルフィー・ポニィ', 'Effect Monster', 'Beast', 'EARTH', 2, 400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方对怪兽的召唤·特殊召唤成功的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到持有者手卡。那之后，可以从自己墓地选「童话动物·小马」以外的1只2星以下的兽族怪兽加入手卡。 ②：自己结束阶段才能发动。这张卡从手卡特殊召唤。'),
(20003027, 'Melffy Puppy', '梅尔菲・帕皮', 'メルフィー・パピィ', 'Effect Monster', 'Beast', 'EARTH', 2, 300, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽召唤·特殊召唤的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到手卡。那之后，可以把除「童话动物·小狗」外的1只2星以下的兽族怪兽从卡组特殊召唤。 ②：自己结束阶段才能发动。这张卡从手卡特殊召唤。'),
(20129614, 'Melffy Rabby', '梅尔菲・拉比', 'メルフィー・ラビィ', 'Normal Monster', 'Beast', 'EARTH', 2, NULL, 2100, '小兔子最喜欢这树桩。经常爬上去向四处张望。  童话动物之森有好多个性丰富可爱的动物们。 那边发现树桩后不由自主就想要坐下来的你！ 来，跟着小兔子一块儿去寻找童话动物朋友吧♪'),
(76981308, 'Melffy Staring Contest', '与梅尔菲瞪瞪眼', 'メルフィーとにらめっこ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把手卡1只兽族怪兽给对方观看才能发动。和那只怪兽卡名不同的1只「童话动物」怪兽从自己的卡组·墓地加入手卡，给人观看的怪兽回到卡组最下面。 ②：对方战斗阶段开始时才能发动。手卡的「童话动物」怪兽任意数量给对方观看，只在战斗阶段内公开。 ③：对方场上的怪兽的攻击力下降这张卡的②的效果公开中的怪兽的攻击力·守备力的合计数值。'),
(37256135, 'Melffy Tag', '梅尔菲追追乐', 'メルフィーのおいかけっこ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「童话动物」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(98416533, 'Melffy Wally', '梅尔菲・瓦莱皮', 'メルフィー・ワラビィ', 'Effect Monster', 'Beast', 'EARTH', 2, NULL, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽召唤·特殊召唤的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到手卡。那之后，可以从卡组把「童话动物·小小袋鼠」以外的2只「童话动物」怪兽特殊召唤（同名卡最多1张）。 ②：自己结束阶段才能发动。这张卡从手卡特殊召唤。'),
(64245689, 'Meliae of the Trees', '墨利阿斯的木灵', 'メリアスの木霊', 'XYZ Monster', 'Plant', 'EARTH', 3, 1700, 900, '地属性3星怪兽×2 1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●从卡组把1只植物族怪兽送去墓地。 ●从自己墓地选择1只植物族怪兽表侧守备表示特殊召唤。'),
(31458630, 'Melodious Concerto', '幻奏协奏曲', '幻奏協奏曲', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·场上的怪兽作为融合素材，把1只天使族融合怪兽融合召唤。那个时候，自己的灵摆区域存在的融合素材怪兽也能作为融合素材使用。 ②：这张卡在墓地存在的状态，「幻奏」融合怪兽被送去自己墓地的场合才能发动（伤害步骤也能发动）。这张卡回到卡组最下面。那之后，自己抽1张。'),
(63804637, 'Melodious Illusion', '幻奏的幻像', '幻奏のイリュージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「幻奏」怪兽为对象才能发动。这个回合，那只自己怪兽不受对方的魔法·陷阱卡的效果影响，同1次的战斗阶段中可以作2次攻击。'),
(88942504, 'Melomelody the Brass Djinn', '管魔人 迷迷旋律', '管魔人メロメロメロディ', 'XYZ Monster', 'Fiend', 'LIGHT', 3, 1400, 1600, '3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择自己场上1只名字带有「魔人」的超量怪兽才能发动。这个回合，选择的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(49905576, 'Meltiel, Sage of the Sky', '天空圣者 莫提乌斯', '天空聖者メルティウス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1200, '①：只要这张卡在怪兽区域存在，每次自己或者对方把反击陷阱卡发动，自己回复1000基本分，场上有「天空的圣域」存在的场合，再选对方场上1张卡破坏。'),
(23288411, 'Mementoal Tecuhtlica - Combined Creation', '冥骸合龙－冥铭途拉尔泰库特利卡', '冥骸合竜－メメントラル・テクトリカ', 'Effect Monster', 'Wyrm', 'EARTH', 11, 5000, 5000, '这张卡不能通常召唤。让这张卡以外的自己的手卡·墓地的「莫忘」怪兽5种类各1只回到卡组·额外卡组的场合才能从手卡·墓地特殊召唤。 ①：自己场上没有其他怪兽存在的场合，这张卡可以向对方怪兽全部各作1次攻击。 ②：1回合1次，对方把魔法·陷阱·怪兽的效果发动的场合才能发动。从自己的手卡·墓地把1只「莫忘」怪兽特殊召唤。'),
(43338320, 'Mementomictlan', '冥骸府－冥铭途兰', '冥骸府－メメントラン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的「莫忘」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：自己场上的怪兽被战斗·效果破坏的场合，以那之内的1只为对象才能发动。比那只怪兽等级低的1只「莫忘」怪兽从自己的手卡·墓地特殊召唤。 ③：自己结束阶段，以自己墓地1张「莫忘」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(14529511, 'Mementomictlan Tecuhtlica - Creation King', '冥骸王－冥铭途兰泰库特利卡', '冥骸王－メメントラン・テクトリカ', 'Fusion Monster', 'Illusion', 'EARTH', 9, 3000, 2000, '「莫忘」怪兽×3 这个卡名的①②③的效果1回合各能使用1次，①②的效果在同一连锁上不能发动。 ①：这张卡融合召唤的场合才能发动。从卡组·额外卡组把3张「莫忘」卡送去墓地。 ②：自己·对方回合，以自己场上的「莫忘」怪兽和对方场上的卡各相同数量为对象才能发动。那些卡破坏。 ③：把墓地的这张卡除外才能发动。从卡组把1张「冥骸府-莫忘冥府」加入手卡。'),
(54207171, 'Mementotlan Akihiron', '冥铭途・卡可塔斯', 'メメント・カクタス', 'Effect Monster', 'Aqua', 'WATER', 5, 1700, 1400, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。这个回合中，9星以上的「莫忘」怪兽可以直接攻击。 ②：这张卡被效果破坏的场合，以这张卡以外的自己的墓地·除外状态的1张「莫忘」卡为对象才能发动。那张卡加入手卡。 ③：这张卡在墓地存在的状态，自己的手卡·场上（表侧表示）的「莫忘」怪兽被战斗·效果破坏的场合才能发动。这张卡特殊召唤。'),
(54550967, 'Mementotlan Angwitch', '冥铭途・天魔女', 'メメント・エンウィッチ', 'Effect Monster', 'Spellcaster', 'DARK', 3, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「莫忘天魔女」以外的1只「莫忘」怪兽加入手卡。 ②：以自己墓地1只2星以下的「莫忘」怪兽为对象才能发动。自己场上1只「莫忘」怪兽破坏，作为对象的怪兽特殊召唤。'),
(16227633, 'Mementotlan Bone Back', '冥铭途・骨回归', 'メメント・ボーン・バック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的「莫忘」怪兽因对方从场上离开的场合才能发动。从手卡·卡组把1只「冥骸合龙-莫忘冥地王灵」无视召唤条件特殊召唤。 ②：这张卡在墓地存在的状态，自己墓地的「莫忘」怪兽因对方从墓地离开的场合，把这张卡除外才能发动。从手卡·卡组把「莫忘」怪兽尽可能特殊召唤（同名卡最多1张）。'),
(80722024, 'Mementotlan Bone Party', '冥铭途・骨派对', 'メメント・ボーン・パーティー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·场上（表侧表示）1只「莫忘」怪兽破坏，从卡组选和那只怪兽卡名不同的1只「莫忘」怪兽加入手卡或守备表示特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「莫忘」怪兽为对象才能发动。这个回合，那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(79600447, 'Mementotlan Cranium Burst', '冥铭途・颅骨爆发', 'メメント・クレニアム・バースト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果在同一连锁上只能发动1次。 ①：可以攻击的对方怪兽只要自己场上有「莫忘」怪兽存在，必须向那之内的攻击力最高的怪兽作出攻击。 ②：对方把场上的怪兽的效果发动时，以自己场上1只「冥骸合龙-莫忘冥地王灵」为对象才能发动。那只怪兽的攻击力·守备力下降1000，那个发动的效果无效。'),
(18165869, 'Mementotlan Dark Blade', '冥铭途・暗黑剑', 'メメント・ダークソード', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，从手卡丢弃1张「莫忘」卡，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：自己主要阶段才能发动。自己场上1只「莫忘」怪兽破坏，从卡组把1只3星以下的「莫忘」怪兽特殊召唤。'),
(43215738, 'Mementotlan Fracture Dance', '冥铭途・碎骨舞', 'メメント・フラクチャー・ダンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「莫忘」怪兽存在的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，自己场上有「冥骸合龙-莫忘冥地王灵」存在的场合，可以把场上1张卡破坏。 ②：自己的「莫忘」怪兽和对方怪兽进行战斗的攻击宣言时，把墓地的这张卡除外才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降1000。'),
(66518509, 'Mementotlan Fusion', '冥骸融合－冥铭途结合', '冥骸融合－メメント・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：双方的主要阶段才能发动。包含「莫忘」怪兽的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。这个回合是已有自己怪兽被效果破坏的场合，也能让自己墓地的「莫忘」怪兽回到卡组作为融合素材。 ②：自己主要阶段把墓地的这张卡除外才能发动。自己场上1只怪兽破坏，从卡组把1张「莫忘」魔法·陷阱卡加入手卡。'),
(52918032, 'Mementotlan Ghattic', '冥铭途・楼中怪', 'メメント・ウラモン', 'Effect Monster', 'Fiend', 'DARK', 2, 550, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「莫忘阁楼怪」以外的自己墓地1张「莫忘」卡为对象才能发动。那张卡加入手卡。 ②：这张卡被「莫忘」怪兽的效果送去墓地的场合才能发动。这张卡特殊召唤。'),
(17943271, 'Mementotlan Goblin', '冥铭途・格布林', 'メメント・ゴブリン', 'Effect Monster', 'Fiend', 'DARK', 1, 400, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，自己场上有「冥骸合龙-莫忘冥地王灵」存在的场合，把这张卡从手卡丢弃才能发动。这个回合中，对方不能把自己场上的「莫忘」怪兽作为效果的对象。 ②：自己主要阶段才能发动。自己场上1只「莫忘」怪兽破坏，从卡组把「莫忘哥布林」以外的最多2张「莫忘」卡送去墓地（同名卡最多1张）。'),
(81945676, 'Mementotlan Mace', '冥铭途・梅思', 'メメント・メイス', 'Effect Monster', 'Fairy', 'LIGHT', 1, 400, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：对方主要阶段，自己场上有「冥骸合龙-莫忘冥地王灵」存在的场合，把这张卡从手卡丢弃，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。 ②：自己主要阶段才能发动。自己场上1只「莫忘」怪兽破坏，从卡组把「莫忘心钥精」以外的1张「莫忘」卡加入手卡。'),
(50042011, 'Mementotlan Shleepy', '冥铭途・催眠羊', 'メメント・スリーピィ', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己怪兽被效果破坏的自己·对方回合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「莫忘」融合怪兽融合召唤。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把「莫忘催眠羊」以外的1张「莫忘」卡送去墓地。'),
(81677154, 'Mementotlan Tatsunootoshigo', '冥铭途・海马', 'メメント・シーホース', 'Effect Monster', 'Beast', 'EARTH', 5, 1350, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有「莫忘」怪兽以外的表侧表示怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。自己场上1只「莫忘」怪兽破坏，等级合计最多到破坏的怪兽的原本等级以下为止，从卡组把「莫忘」怪兽送去墓地（同名卡最多1张）。'),
(19181420, 'Mementotlan Twin Dragon', '冥铭途・双头龙', 'メメント・ツイン・ドラゴン', 'Fusion Monster', 'Thunder', 'LIGHT', 7, 2800, 2100, '「莫忘」怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。自己的手卡·场上（表侧表示）1只「莫忘」怪兽破坏，从卡组把最多2只「莫忘」怪兽加入手卡（同名卡最多1张）。 ②：自己的「莫忘」怪兽战斗破坏的怪兽不去墓地而除外。 ③：融合召唤的这张卡被破坏的场合才能发动。从自己墓地把1只6星以下的「莫忘」怪兽特殊召唤。'),
(55272555, 'Mementotlan-Horned Dragon', '冥铭途・角龙', 'メメント・ホーン・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 2850, 2350, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地有「莫忘」怪兽3种类以上存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡被效果破坏的场合，以包含自己场上的「莫忘」卡的场上3张表侧表示卡为对象才能发动。那些卡破坏。'),
(84731222, 'Memories of Hope', '希望之记忆', '希望の記憶', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己从卡组抽出自己场上的「No.」超量怪兽种类的数量。'),
(75675029, 'Memory Crush King', '记忆破坏王', '記憶破壊王', 'Effect Monster', 'Fiend', 'DARK', 5, 2000, NULL, '这张卡直接攻击给与对方基本分战斗伤害时，对方墓地存在的同调怪兽全部从游戏中除外，给与对方基本分那个数量×1000的数值的伤害。'),
(48700891, 'Memory Crusher', '记忆破坏者', '記憶破壊者', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 600, '这张卡对对方玩家直接攻击造成伤害的场合，给与对方基本分对方额外卡组的卡数×100分数值的伤害。'),
(71098407, 'Memory Loss', '健忘', 'もの忘れ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上表侧攻击表示存在的怪兽的效果发动时才能发动。那个发动的效果无效，那只怪兽变成表侧守备表示。'),
(60080151, 'Memory of an Adversary', '好对手的记忆', '好敵手の記憶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。自己受到攻击怪兽的攻击力数值的伤害，那只怪兽从游戏中除外。下次的对方回合的结束阶段时，这个效果除外的怪兽在自己场上特殊召唤。'),
(36565699, 'Mental Seeker', '心灵探索者', 'メンタルシーカー', 'Tuner Monster', 'Psychic', 'EARTH', 3, 800, 600, '从游戏中除外的这张卡特殊召唤成功时，从对方卡组上面把3张卡翻开，自己从那之中选择1张从游戏中除外，剩下的卡回到卡组。'),
(30291086, 'Mental Tuner', '心灵协调', 'メンタル・チューナー', 'Tuner Monster', 'Psychic', 'LIGHT', 3, 200, 2100, '这个卡名的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●把光·暗属性怪兽各最多1只从自己的手卡·墓地除外才能发动。直到回合结束时这张卡的等级上升或者下降除外数量的数值。 ●以除外的自己的光·暗属性怪兽各最多1只为对象才能发动。那些怪兽回到墓地，直到回合结束时这张卡的等级上升或者下降回去数量的数值。'),
(53832650, 'Meotoko', '巴比伦', 'バビロン', 'Normal Monster', 'Beast', 'EARTH', 2, 700, 600, '长有独眼的巨大怪兽。从眼睛之中发出光线攻击。'),
(34198387, 'Meowseclick', '触点抖动啁啾猫', 'ニャータリング', 'Effect Monster', 'Cyberse', 'EARTH', 4, 1400, 1100, '这个卡名的①的效果1回合只能使用1次。 ①：场地魔法卡发动的场合才能发动。这张卡从手卡特殊召唤。双方的场地区域有表侧表示卡存在的场合，再在这个回合让这张卡不会被战斗·效果破坏。 ②：只要这张卡在怪兽区域存在，自己回合内，对方的场地区域的表侧表示的卡的效果无效化，对方回合内，自己的场地区域的表侧表示的卡的效果无效化。'),
(64442155, 'Merciful Machine Angel', '深怀慈悲的机械天使', '慈悲深き機械天使', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己的手卡·场上1只「电子化天使」仪式怪兽解放才能发动。自己从卡组抽2张，那之后选1张手卡回到卡组最下面。这张卡的发动后，直到回合结束时自己不是仪式怪兽不能特殊召唤。'),
(34926568, 'Merciless Scorpion of Serket', '守护兽 塞尔凯特', '守護獣セルケト', 'Effect Monster', 'Fairy', 'EARTH', 6, 2500, 2000, '这张卡不能通常召唤。「守护兽 塞勒凯特」1回合1次在自己场上有「王家的神殿」存在的状态，从手卡·卡组把1只10星以上的怪兽除外的场合可以特殊召唤。 ①：1回合1次，自己主要阶段才能发动。把1张「王家的神殿」或者有那个卡名记述的魔法卡从卡组加入手卡。 ②：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏，这张卡的攻击力上升破坏的怪兽的原本攻击力一半数值。'),
(101303084, 'Mercurium the Living Quicksilver', NULL, NULL, 'XYZ Monster', 'Aqua', 'DARK', 10, 3000, 3000, NULL),
(9940036, 'Mereologic Aggregator', '分体聚合者', 'メレオロジック・アグリゲーター', 'XYZ Monster', 'Cyberse', 'DARK', 9, 2600, 3000, '9星怪兽×2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从额外卡组把1只怪兽送去墓地。 ②：以最多有这张卡的超量素材数量的自己墓地的怪兽为对象才能发动。作为对象的怪兽数量的这张卡的超量素材取除，把作为对象的怪兽作为这张卡的超量素材。 ③：这张卡被送去墓地的场合，以场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(3580032, 'Merlin', '传说的预言者 梅林', '伝説の預言者マーリン', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1400, 500, '「传说的预言者 梅林」的①②③的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从卡组把1只「圣骑士」怪兽特殊召唤。这个效果发动的回合，自己不是「圣骑士」怪兽不能特殊召唤。 ②：把墓地的这张卡除外才能发动。把1只「圣骑士」同调怪兽同调召唤。这个效果在对方回合也能发动。 ③：把墓地的这张卡除外才能发动。把1只「圣骑士」超量怪兽超量召唤。这个效果在对方回合也能发动。'),
(4252828, 'Mermaid Archer', '海洋弓手', 'シー・アーチャー', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1200, 200, '1回合1次，可以把自己场上表侧表示存在的3星以下的怪兽当作装备卡使用只有1只给这张卡装备。这个效果把怪兽装备的场合，这张卡的攻击力上升800。这张卡被破坏的场合，可以作为代替把装备的怪兽破坏。'),
(24435369, 'Mermaid Knight', '人鱼骑士', 'マーメイド・ナイト', 'Effect Monster', 'Aqua', 'WATER', 4, 1500, 700, '①：只要场上有「海」存在，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(87047161, 'Mermaid Shark', '人鱼鲨', 'マーメイド・シャーク', 'Effect Monster', 'Fish', 'WATER', 1, 100, 300, '这张卡召唤成功时，可以从卡组把1只3～5星的鱼族怪兽加入手卡。'),
(23545031, 'Mermail Abyssalacia', '水精鳞－萨拉喀邃渊', '水精鱗－サラキアビス', 'Link Monster', 'Sea Serpent', 'WATER', NULL, 1600, NULL, '鱼族·海龙族·水族怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡所连接区的怪兽的攻击力·守备力上升500。 ②：对方回合把1张手卡送去墓地才能发动。从卡组把1只「水精鳞」怪兽加入手卡。 ③：这张卡被对方怪兽的攻击或者对方的效果破坏的场合，从卡组把1只水属性怪兽送去墓地，以自己墓地1只水属性怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(75180828, 'Mermail Abyssbalaen', '水精鳞-大蓝深渊鲸', '水精鱗－サルフアビス', 'Effect Monster', 'Aqua', 'WATER', 7, 2500, 2000, '自己的主要阶段时，从手卡把4只名字带有「水精鳞」的怪兽丢弃去墓地才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤时，这张卡的攻击力上升500，选择最多有自己墓地的名字带有「水精鳞」的怪兽数量的对方场上的卡破坏。此外，可以通过把这张卡以外的表侧攻击表示存在的1只名字带有「水精鳞」的怪兽解放，这个回合这张卡向守备表示怪兽攻击的场合，不进行伤害计算把那只怪兽破坏。'),
(74298287, 'Mermail Abyssdine', '水精鳞－邃渊蒂妮', '水精鱗－アビスディーネ', 'Effect Monster', 'Aqua', 'WATER', 3, 1000, 200, '自己场上有名字带有「水精鳞」的怪兽存在的场合，这张卡用卡的效果从卡组或者墓地加入手卡时，这张卡可以从手卡特殊召唤。此外，这张卡用名字带有「水精鳞」的怪兽的效果特殊召唤成功时，可以从自己墓地选择1只3星以下的名字带有「水精鳞」的怪兽特殊召唤。「水精鳞-深渊蒂妮」的效果1回合只能使用1次。'),
(74371660, 'Mermail Abyssgaios', '水精鳞－盖奥邃渊', '水精鱗－ガイオアビス', 'XYZ Monster', 'Aqua', 'WATER', 7, 2800, 1600, '水属性7星怪兽×2 只要持有超量素材的这张卡在场上表侧表示存在，5星以上的怪兽不能攻击。此外，1回合1次，把这张卡1个超量素材取除才能发动。持有比这张卡的攻击力低的攻击力的对方场上的怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(69293721, 'Mermail Abyssgunde', '水精鳞－邃渊昆德', '水精鱗－アビスグンデ', 'Effect Monster', 'Aqua', 'WATER', 3, 1400, 800, '这张卡从手卡丢弃去墓地的场合，可以从自己墓地选择「水精鳞-深渊昆德」以外的1只名字带有「水精鳞」的怪兽特殊召唤。「水精鳞-深渊昆德」的效果1回合只能使用1次。'),
(96682430, 'Mermail Abysshilde', '水精鳞－邃渊希德', '水精鱗－アビスヒルデ', 'Effect Monster', 'Aqua', 'WATER', 3, 1300, 400, '这张卡被送去墓地的场合，可以从手卡把「水精鳞-深渊希德」以外的1只名字带有「水精鳞」的怪兽特殊召唤。「水精鳞-深渊希德」的效果1回合只能使用1次。'),
(37781520, 'Mermail Abyssleed', '水精鳞-利兹深渊鱼', '水精鱗－リードアビス', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2700, 1000, '自己的主要阶段时，从手卡把这张卡以外的3只水属性怪兽丢弃去墓地才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤成功时，可以从自己墓地选择1张名字带有「深渊」的魔法·陷阱卡加入手卡。此外，可以通过把这张卡以外的自己场上表侧攻击表示存在的1只名字带有「水精鳞」的怪兽解放，对方手卡随机1张送去墓地。「水精鳞-利兹深渊鱼」的这个效果1回合只能使用1次。'),
(23899727, 'Mermail Abysslinde', '水精鳞－邃渊琳德', '水精鱗－アビスリンデ', 'Effect Monster', 'Aqua', 'WATER', 3, 1500, 1200, '场上的这张卡被破坏送去墓地的场合，可以从卡组把「水精鳞-深渊琳德」以外的1只名字带有「水精鳞」的怪兽特殊召唤。「水精鳞-深渊琳德」的效果1回合只能使用1次。'),
(95466842, 'Mermail Abysslung', '水精鳞-深渊肺鱼兵', '水精鱗－アビスラング', 'Effect Monster', 'Fish', 'WATER', 4, 1200, 1800, '只要这张卡在场上表侧表示存在，对方不能选择其他的水属性怪兽作为攻击对象。此外，只要这张卡在场上表侧表示存在，自己场上的水属性怪兽的攻击力上升300。'),
(21767650, 'Mermail Abyssmander', '水精鳞-深渊鲵鱼兵', '水精鱗－アビスマンダー', 'Effect Monster', 'Fish', 'WATER', 4, 100, 2000, '可以把墓地的这张卡从游戏中除外，从以下效果选择1个发动。 ●自己场上的全部名字带有「水精鳞」的怪兽的等级上升1星。 ●自己场上的全部名字带有「水精鳞」的怪兽的等级上升2星。'),
(21954587, 'Mermail Abyssmegalo', '水精鳞－巨齿邃渊', '水精鱗－メガロアビス', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2400, 1900, '①：从手卡把这张卡以外的2只水属性怪兽丢弃去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡的①的效果特殊召唤成功时才能发动。从卡组把1张「深渊」魔法·陷阱卡加入手卡。 ③：把这张卡以外的自己场上1只表侧攻击表示的水属性怪兽解放才能发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(71133680, 'Mermail Abyssnerei', '水精鳞-深渊海仙女', '水精鱗－ネレイアビス', 'Effect Monster', 'Aqua', 'WATER', 3, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以自己场上1只水属性怪兽为对象才能发动。选那只怪兽以外的自己的手卡·场上1只水属性怪兽破坏，作为对象的怪兽的攻击力·守备力直到回合结束时上升这个效果破坏的怪兽的原本数值。这个效果在对方回合也能发动。 ②：这张卡从场上送去墓地的场合才能发动。自己从卡组抽1张，那之后选1张手卡丢弃。'),
(282886, 'Mermail Abyssnose', '水精鳞-深渊象鼻鱼兵', '水精鱗－アビスノーズ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 1500, '这张卡战斗破坏对方怪兽送去墓地时，把手卡1只水属性怪兽丢弃去墓地才能发动。从卡组把1只名字带有「水精鳞」的怪兽表侧守备表示特殊召唤。「水精鳞-深渊象鼻鱼兵」的效果1回合只能使用1次。'),
(28577986, 'Mermail Abyssocea', '水精鳞-深渊水仙女', '水精鱗－オーケアビス', 'Effect Monster', 'Aqua', 'WATER', 3, 1100, 1900, '自己的主要阶段时，选择自己场上1只名字带有「水精鳞」的怪兽才能发动。等级合计最多到选择的怪兽的等级以下为止，从卡组把4星以下的名字带有「水精鳞」的怪兽任意数量特殊召唤。那之后，选择的怪兽送去墓地。「水精鳞-深渊水仙女」的效果1回合只能使用1次。'),
(58471134, 'Mermail Abysspike', '水精鳞－邃渊鳄雀鳝', '水精鱗－アビスパイク', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 800, '这张卡召唤·特殊召唤成功时，把手卡1只水属性怪兽丢弃去墓地才能发动。从卡组把1只3星的水属性怪兽加入手卡。「水精鳞-深渊雀鳝兵」的效果1回合只能使用1次。'),
(22446869, 'Mermail Abyssteus', '水精鳞－恐甲邃渊', '水精鱗－ディニクアビス', 'Effect Monster', 'Aqua', 'WATER', 7, 1700, 2400, '这个卡名的②的效果1回合只能使用1次。 ①：从手卡把这张卡以外的1只水属性怪兽丢弃去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡的①的效果特殊召唤成功时才能发动。从卡组把1只4星以下的「水精鳞」怪兽加入手卡。'),
(59170782, 'Mermail Abysstrite', '水精鳞－邃渊特里忒', '水精鱗－アビストリーテ', 'XYZ Monster', 'Sea Serpent', 'WATER', 3, 1600, 2800, '3星怪兽×3 自己场上的名字带有「水精鳞」的怪兽1只成为对方的魔法·陷阱卡的效果的对象时或者成为对方怪兽的攻击对象时，把这张卡1个超量素材取除才能发动。那个对象转移为自己场上的作为正确对象的这张卡。这张卡被破坏送去墓地时，可以从自己墓地选择「水精鳞-深渊特里忒」以外的1只名字带有「水精鳞」的怪兽特殊召唤。'),
(22076135, 'Mermail Abyssturge', '水精鳞－邃渊鲟', '水精鱗－アビスタージ', 'Effect Monster', 'Fish', 'WATER', 4, 1700, 1100, '这张卡召唤·特殊召唤成功时，把手卡1只水属性怪兽丢弃去墓地才能发动。从自己墓地选择1只3星以下的水属性怪兽加入手卡。「水精鳞-深渊鲟鱼兵」的效果1回合只能使用1次。'),
(69385019, 'Mermail King - Neptabyss', '皇之水精鳞－尼普邃渊', '皇たる水精鱗－ネプトアビス', 'Link Monster', 'Sea Serpent', 'WATER', NULL, 2300, NULL, '包含鱼族·海龙族·水族怪兽的怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：对方不能把这张卡所连接区的水属性怪兽作为效果的对象。 ②：水属性怪兽为让卡的效果发动而被送去墓地的场合才能发动。从自己的卡组·墓地选1张「深渊」装备魔法卡加入手卡或给这张卡装备。 ③：这张卡被对方破坏的场合才能发动。从卡组把1只「海皇」怪兽或「水精鳞」怪兽加入手卡。'),
(53085623, 'Mermail Shadow Squad', '水精鳞的深影队', '水精鱗の深影隊', 'Effect Monster', 'Sea Serpent', 'WATER', 3, NULL, 1900, '这个卡名在规则上也当作「海皇」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：把1张手卡丢弃去墓地才能发动。自己场上的全部水属性怪兽的等级直到回合结束时变成7星。 ②：这张卡为让水属性怪兽的效果发动而被送去墓地的场合发动。除「水精鳞的深影队」外的4星以下的1只「海皇」怪兽或「水精鳞」怪兽从卡组特殊召唤。这个回合，自己不是水属性怪兽不能从额外卡组特殊召唤。'),
(81019803, 'Merry Melffys', '飘飘然的梅尔菲们', 'うきうきメルフィーズ', 'Synchro Monster', 'Beast', 'EARTH', 4, 1500, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽回到手卡。 ②：对方把怪兽召唤·特殊召唤的场合或者这张卡被选择作为对方怪兽的攻击对象的场合才能发动。这张卡回到额外卡组。那之后，可以从额外卡组把1只「童话动物」超量怪兽特殊召唤。'),
(48642904, 'Mesmeric Control', '催眠术', '催眠術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：下次的对方回合，对方不能把怪兽的表示形式变更。'),
(97433739, 'Message in a Bottle', '对未来的所思', '未来への思い', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地3只等级不同的怪兽才能发动。选择的3只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力变成0，效果无效化。那之后，自己没有进行超量召唤的场合，这个回合的结束阶段时自己失去4000基本分。此外，这张卡发动的回合，自己不能作超量召唤以外的特殊召唤。'),
(44656491, 'Messenger of Peace', '和平使者', '平和の使者', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上表侧表示存在的攻击力1500以上的怪兽不能攻击宣言。这张卡的控制者在每次自己的准备阶段支付100基本分。或者不支付100基本分让这张卡破坏。'),
(49808196, 'Metabo Globster', '代谢吸食怪', 'メタボ・サッカー', 'Effect Monster', 'Fiend', 'DARK', 3, 800, 300, '把这张卡解放对暗属性怪兽的上级召唤成功时，在自己场上把3只「代谢衍生物」（暗·1星·恶魔族·攻0/守0）守备表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(49808197, 'Metabo Token', '代谢吸食怪', 'メタボ・サッカー', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(37792478, 'Metabo-Shark', '代谢鲨', 'メタボ・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1800, 500, '这张卡召唤成功时，可以选择自己墓地存在的2只鱼族怪兽回到卡组。'),
(74530899, 'Metaion, the Timelord', '时械神 梅塔伊恩', '時械神メタイオン', 'Effect Monster', 'Fairy', 'FIRE', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，攻击表示的这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。这张卡以外的场上的怪兽全部回到持有者手卡，给与对方回去数量×300伤害。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(65957473, 'Metal Armored Bug', '铁钢装甲虫', '鉄鋼装甲虫', 'Normal Monster', 'Insect', 'EARTH', 8, 2800, 1500, '全身覆盖着厚厚装甲的巨大昆虫型生物。毫不留情的破坏着碍事者。'),
(75646520, 'Metal Detector', '金属探知器', '金属探知器', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '永续陷阱卡发动时才能发动。直到回合结束时场上的全部永续陷阱卡的效果无效。'),
(9293977, 'Metal Dragon', '金属龙', 'メタル・ドラゴン', 'Fusion Monster', 'Machine', 'WIND', 6, 1850, 1700, '「钢铁巨神像」＋「下级龙」'),
(24874631, 'Metal Fiend Token', '恶魔的圣域', 'デビルズ・サンクチュアリ', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(55998462, 'Metal Fish', '金属鱼', 'メタル・フィッシュ', 'Normal Monster', 'Machine', 'WATER', 5, 1600, 1900, '金属鱼，用刀一样锋利的尾巴切开对方。'),
(68339286, 'Metal Guardian', '金属守护者', 'メタル・ガーディアン', 'Normal Monster', 'Fiend', 'DARK', 5, 1150, 2150, '守护魔界宝物的恶魔在黑暗中守备相当强。'),
(29157292, 'Metal Illusionist', '钢铁幻象师', '鋼鉄の幻想師', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「金属化」陷阱卡在自己场上盖放。自己墓地有「金属化·强化反射装甲」存在的场合，再让自己可以抽1张。 ②：只要这张卡在怪兽区域存在，这张卡的等级在对方回合内上升4星。 ③：宣言1个种族才能发动。这张卡直到对方回合结束时变成宣言的种族。'),
(26905245, 'Metal Reflect Slime', '金属反射史莱姆', 'メタル・リフレクト・スライム', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（水族·水·10星·攻0/守3000）在怪兽区域守备表示特殊召唤（也当作陷阱卡使用）。 ②：这张卡的效果特殊召唤的这张卡不能攻击。'),
(7200041, 'Metal Shooter', '金属射手', 'メタル・シューター', 'Effect Monster', 'Machine', 'LIGHT', 5, 800, 800, '这张卡召唤成功时，给这张卡放置2个指示物。这个效果每放置有1个指示物，这张卡的攻击力上升800。这张卡被其他卡的效果破坏的场合，把这张卡的1个指示物取除作代替。'),
(27704731, 'Metalflame Swordsman', '钢炎之剑士', '鋼炎の剣士', 'Effect Monster', 'Machine', 'FIRE', 6, 2500, 1600, '这张卡不能通常召唤，用把5星以上的战士族怪兽解放发动的「金属化·强化反射装甲」的效果可以特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。把「钢炎之剑士」以外的有「金属化·强化反射装甲」的卡名记述的1张卡从卡组加入手卡，这张卡回到卡组。 ②：只要这张卡在怪兽区域存在，每次对方把效果发动，这张卡的攻击力上升300，给与对方500伤害。'),
(81612598, 'Metalfoes Adamante', '炼装勇士·精金超人', 'メタルフォーゼ・アダマンテ', 'Fusion Monster', 'Psychic', 'FIRE', 5, 2500, 2500, '「炼装」怪兽＋攻击力2500以下的怪兽'),
(69711728, 'Metalfoes Combination', '炼装联合', 'メタルフォーゼ・コンビネーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，融合怪兽融合召唤的场合，以比那融合怪兽等级低的自己墓地1只「炼装」怪兽为对象才能把这个效果发动。那只怪兽特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1只「炼装」怪兽加入手卡。'),
(33327029, 'Metalfoes Counter', '炼装反击', 'メタルフォーゼ・カウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的卡被战斗·效果破坏的场合才能发动。从卡组把1只「炼装」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从自己的额外卡组把1只表侧表示的「炼装」灵摆怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(54401832, 'Metalfoes Crimsonite', '炼装勇士·绯金红巨甲', 'メタルフォーゼ・カーディナル', 'Fusion Monster', 'Psychic', 'FIRE', 9, 3000, 3000, '「炼装」怪兽＋攻击力3000以下的怪兽×2'),
(73594093, 'Metalfoes Fusion', '炼装融合', '錬装融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把「炼装」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：这张卡在墓地存在的场合才能发动。墓地的这张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(33256280, 'Metalfoes Goldriver', '炼装勇士·金驰', 'メタルフォーゼ・ゴルドライバー', 'Pendulum Normal Monster', 'Psychic', 'FIRE', 4, 1900, 500, '闪耀着黄金车身的光芒，以豪爽的漂移跑法横扫敌军。尽管经常都很夸张地出现侧滑失控，但本人坚定立场地表示那就是必杀技。'),
(4688231, 'Metalfoes Mithrilium', '炼装勇士·秘银天使', 'メタルフォーゼ・ミスリエル', 'Fusion Monster', 'Psychic', 'FIRE', 6, 2600, 1000, '「炼装」怪兽＋灵摆怪兽 「炼装勇士·秘银天使」的①的效果1回合只能使用1次。 ①：以自己墓地2张「炼装」卡和场上1张卡为对象才能发动。墓地的作为对象的卡回到卡组，场上的作为对象的卡回到持有者手卡。 ②：这张卡从场上送去墓地的场合才能发动。选1只自己的额外卡组的表侧表示的「炼装」灵摆怪兽或者自己墓地的「炼装」灵摆怪兽特殊召唤。'),
(28016193, 'Metalfoes Orichalc', '炼装勇士·山铜狂战士', 'メタルフォーゼ・オリハルク', 'Fusion Monster', 'Psychic', 'FIRE', 8, 2800, 2200, '「炼装」怪兽×2 ①：自己的「炼装」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的2倍数值的战斗伤害。 ②：这张卡从场上送去墓地的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(7868571, 'Metalfoes Silverd', '炼装勇士·银鸟', 'メタルフォーゼ・シルバード', 'Pendulum Normal Monster', 'Psychic', 'FIRE', 3, 1700, 100, '操纵着白银亚光速喷气机的美丽狙击手。想捕捉到用超常识速度飞驰的她是几乎不可能的事，没有办法能从快如光速时施展的一击中逃脱出去。'),
(60473572, 'Metalfoes Steelen', '炼装勇士·钢人', 'メタルフォーゼ・スティエレン', 'Pendulum Normal Monster', 'Psychic', 'FIRE', 2, NULL, 2100, '当隐藏于黑铁机身中的灵魂觉醒之时，钢铁将升华化作秘金属，成为人机一体的勇士。令刻于其身的魂钢燃烧起来吧！——炼装融合！！'),
(56518311, 'Metalfoes Vanisher', '炼装勇士·消灭', 'メタルフォーゼ・バニッシャー', 'Pendulum Effect Monster', 'Psychic', 'FIRE', 9, 2900, 1900, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：以包含「炼装」卡的自己场上2张表侧表示的卡为对象才能发动。那些卡破坏，这张卡从手卡特殊召唤。 ②：这张卡用「炼装」卡的效果特殊召唤成功的场合，以对方的场上·墓地1只怪兽为对象才能发动。那只怪兽除外。'),
(69351984, 'Metalfoes Volflame', '炼装勇士·钨火', 'メタルフォーゼ・ヴォルフレイム', 'Pendulum Normal Monster', 'Psychic', 'FIRE', 7, 2400, 2000, '拥有赤热魂钢的上级战士。就在与将世界带向终结的红色真龙威胁进行对峙的时候，他得到仿佛彼此呼应而穿越次元出现的光之意志引导，使身披百炼钢甲之术迎来了绽放时刻。'),
(42237854, 'Metalhold the Moving Blockade', '机动要塞 铁堡垒', '機動要塞 メタル・ホールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己场上的机械族·4星怪兽任意数量为对象才能发动。这张卡发动后变成效果怪兽（机械族·地·4星·攻/守0）在怪兽区域特殊召唤。那之后，作为对象的表侧表示怪兽当作装备卡使用给这张卡装备。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力的合计数值，对方不能把其他的自己场上的怪兽作为攻击对象，也不能作为效果的对象。'),
(7369217, 'Metallizing Parasite - Lunatite', '金属化寄生生物-月之衣', 'メタル化寄生生物－ルナタイト', 'Union Effect Monster', 'Aqua', 'WATER', 7, 1000, 500, '1回合只有1次，在自己的主要阶段，场上的这张卡可以当作装备卡使用给自己场上的表侧表示怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。装备怪兽不受对方所控制的魔法卡效果的影响。（1只怪兽可以装备的同盟最多1张，装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(87564935, 'Metallizing Parasite - Soltite', '金属化寄生生物-日之衣', 'メタル化寄生生物－ソルタイト', 'Union Effect Monster', 'Aqua', 'WATER', 7, 1000, 500, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽不会成为对方的效果怪兽的效果的对象，不会被对方的效果怪兽的效果破坏。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(68540059, 'Metalmorph', '金属化·魔法反射装甲', 'メタル化・魔法反射装甲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(32472237, 'Metalrokket Dragon', '金属枪弹龙', 'メタルヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1700, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，和这张卡存在过的区域相同纵列的对方的卡全部破坏。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「金属被甲弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(33114323, 'Metalsilver Armor', '金属银铠甲', 'メタルシルバー・アーマー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：只要装备怪兽在自己场上存在，对方不能把装备怪兽以外的双方的场上·墓地·除外状态的怪兽作为效果的对象。'),
(57761191, 'Metaltron XII, the True Dracombatant', '真龙机兵 十二炼机梅塔特隆', '真竜機兵ダースメタトロン', 'Effect Monster', 'Wyrm', 'LIGHT', 9, 3000, 3000, '这张卡通常召唤的场合，必须把3只怪兽解放作召唤，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：这张卡不受原本种类（怪兽·魔法·陷阱）和为这张卡的上级召唤而解放的卡相同的卡的效果影响。 ②：上级召唤的这张卡被对方破坏的场合才能发动。地·水·炎·风属性的其中1只融合·同调·超量怪兽从额外卡组特殊召唤。'),
(64664373, 'Metaltronus', '共界神渊体', '共界神淵体', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以衍生物以外的对方场上1只表侧表示怪兽为对象才能发动（对方不能对应这张卡的发动把作为对象的怪兽的效果发动）。种族·属性·攻击力之内有2个以上是和作为对象的怪兽相同的1只怪兽从手卡·卡组·额外卡组效果无效特殊召唤，作为对象的怪兽的效果无效。这个效果特殊召唤的怪兽和作为对象的怪兽的卡名相同的场合，可以再把那2只里侧除外。'),
(50705071, 'Metalzoa', '钢铁恶魔兽灵', 'メタル・デビルゾア', 'Effect Monster', 'Machine', 'DARK', 8, 3000, 2300, '这张卡不能通常召唤。把有「金属化·魔法反射装甲」装备的自己场上1只「恶魔兽灵」解放的场合可以从卡组特殊召唤。'),
(27268998, 'Metalzoa X', '钢铁戴比鲁佐亚X', 'メタル・デビルゾアX', 'Effect Monster', 'Machine', 'DARK', 8, 3000, 2300, '这张卡不能通常召唤，用把5星以上的恶魔族怪兽解放发动的「金属化·强化反射装甲」的效果可以特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从卡组把1张「金属化」陷阱卡在自己场上盖放，这张卡回到卡组。 ②：1回合最多2次，对方把魔法·怪兽的效果发动时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(46500985, 'Metamorformation', '炼成阵·构成', 'メタモルF', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「炼装」怪兽的攻击力·守备力上升300。 ②：只要自己的灵摆区域有「炼装」卡存在，效果怪兽以外的自己场上的「炼装」怪兽不受对方的效果影响。'),
(43959432, 'Metamorphortress', '变形黏土要塞', 'メタモル・クレイ・フォートレス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己场上1只4星以上的怪兽为对象才能发动。这张卡发动后变成效果怪兽（岩石族·地·4星·攻/守1000）在怪兽区域特殊召唤。那之后，作为对象的表侧表示怪兽当作装备卡使用给这张卡装备。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡的攻击力·守备力上升这张卡的效果装备的怪兽的攻击力数值，这张卡在攻击的伤害步骤结束时变成守备表示。'),
(41456841, 'Metamorphosed Insect Queen', '究极变异态昆虫女王', '究極変異態・インセクト女王', 'Effect Monster', 'Insect', 'EARTH', 7, 2800, 2400, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：场上有其他的昆虫族怪兽存在的场合，自己场上的昆虫族怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ②：这张卡攻击的伤害步骤结束时，把自己场上1只怪兽解放才能发动。这张卡向对方怪兽可以继续攻击。 ③：自己·对方的结束阶段才能发动。在自己场上把1只「昆虫怪兽衍生物」（昆虫族·地·1星·攻/守100）特殊召唤。'),
(46411259, 'Metamorphosis', '突然变异', '突然変異', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上的1只怪兽作为祭品。从融合卡组把1只等级与作为祭品的怪兽的等级相同的融合怪兽特殊召唤。'),
(89189982, 'Metaphys Armed Dragon', '玄化武装龙', 'メタファイズ・アームド・ドラゴン', 'Normal Monster', 'Wyrm', 'LIGHT', 7, 2800, 1000, '崇高的存在犹如虚幻。那龙伫立于巅峰之上。'),
(54199839, 'Metaphys Ascension', '玄化升天', 'メタファイズ・アセンション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡丢弃1张「玄化」卡才能发动。自己从卡组抽1张。那之后，可以从卡组把1只「玄化」怪兽除外。 ②：这张卡被除外的场合才能发动。从卡组把「玄化升天」以外的1张「玄化」卡加入手卡。'),
(45960523, 'Metaphys Daedalus', '玄化泰达路斯', 'メタファイズ・ダイダロス', 'Effect Monster', 'Wyrm', 'LIGHT', 7, 2600, 1500, '①：这张卡用「玄化」怪兽的效果特殊召唤成功的场合才能发动。这张卡以外的场上的特殊召唤的表侧表示怪兽全部除外。 ②：这张卡被除外的场合，下个回合的准备阶段让除外的这张卡回到卡组才能发动。从卡组把「玄化泰达路斯」以外的1张「玄化」卡除外。'),
(12196873, 'Metaphys Decoy Dragon', '玄化诱饵龙', 'メタファイズ・デコイドラゴン', 'Pendulum Effect Monster', 'Wyrm', 'LIGHT', 2, 300, 200, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己怪兽被选择作为攻击对象时，从自己墓地的怪兽以及除外的自己怪兽之中以1只「玄化」怪兽为对象才能发动。场上的这张卡除外，作为对象的怪兽攻击表示特殊召唤。 ②：这张卡被除外的下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(52714670, 'Metaphys Dimension', '玄化次元', 'メタファイズ・ディメンション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方对怪兽的特殊召唤成功的场合，以除外的1只自己的「玄化」怪兽为对象才能把这个效果发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。 ②：这张卡已在魔法与陷阱区域存在的状态，这张卡以外的自己的「玄化」卡被除外的场合，以对方场上1张卡为对象才能发动。那张卡除外。'),
(45148985, 'Metaphys Executor', '玄化执行神', 'メタファイズ・エグゼキューター', 'Effect Monster', 'Wyrm', 'LIGHT', 10, 3000, 2500, '这张卡不能通常召唤。从自己墓地以及自己场上的表侧表示的卡之中把「玄化」卡5种类各1张除外的场合才能特殊召唤。 ①：场上的这张卡不会被效果破坏，不能用效果除外。 ②：对方场上的卡数量比自己场上的卡多的场合，1回合1次，以除外的1只自己的「玄化」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。'),
(20720928, 'Metaphys Factor', '玄化因子', 'メタファイズ・ファクター', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己在5星以上的「玄化」怪兽召唤的场合需要的解放可以不用。这个效果1回合只能适用1次。这个效果适用召唤的怪兽在下个回合的结束阶段除外。 ②：只要这张卡在场地区域存在，对方不能对应自己的「玄化」怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。'),
(36898537, 'Metaphys Horus', '玄化荷鲁斯龙', 'メタファイズ・ホルス・ドラゴン', 'Synchro Monster', 'Wyrm', 'LIGHT', 6, 2300, 1600, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功的场合，那些作为同调素材的除调整以外的怪兽种类的以下效果各能发动。 ●通常怪兽：这个回合这张卡不受自身以外的卡的效果影响。 ●效果怪兽：以这张卡以外的场上1张表侧表示的卡为对象才能发动。那个效果无效。 ●灵摆怪兽：对方场上1只怪兽由对方选出，自己得到那个控制权。这个回合那只怪兽不能攻击。'),
(72355272, 'Metaphys Nephthys', '玄化奈芙提斯', 'メタファイズ・ネフティス', 'Effect Monster', 'Wyrm', 'LIGHT', 8, 2400, 1600, '①：这张卡用「玄化」怪兽的效果特殊召唤成功的场合才能发动。场上盖放的魔法·陷阱卡全部除外。 ②：这张卡被除外的场合，下个回合的准备阶段让除外的这张卡回到卡组才能发动。从卡组把「玄化奈芙提斯」以外的1张「玄化」卡加入手卡。'),
(19476824, 'Metaphys Ragnarok', '玄化末日龙', 'メタファイズ・ラグナロク', 'Tuner Monster', 'Wyrm', 'LIGHT', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从自己卡组上面把3张卡除外。这张卡的攻击力上升这个效果除外的「玄化」卡数量×300。 ②：这张卡给与对方战斗伤害时才能发动。从卡组把1只5星以上的「玄化」怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。'),
(18743376, 'Metaphys Tyrant Dragon', '玄化暴君龙', 'メタファイズ・タイラント・ドラゴン', 'Effect Monster', 'Wyrm', 'LIGHT', 8, 2900, 2500, '①：「玄化」怪兽的效果特殊召唤的这张卡不受陷阱卡的效果影响，可以在这张卡向怪兽攻击过的场合只再1次继续攻击。 ②：这张卡被除外的场合，下个回合的准备阶段让除外的这张卡回到卡组才能发动。从手卡把1只「玄化」怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。'),
(89208725, 'Metaverse', '虚拟世界', 'メタバース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组选1张场地魔法卡加入手卡或在自己场上发动。'),
(501000001, 'Meteo the Matchless', NULL, NULL, 'Effect Monster', 'Beast-Warrior', 'DARK', 8, 2400, 2000, NULL),
(22398665, 'Meteonis Drytron', '辉龙机巧降星', '流星輝巧群', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：攻击力合计直到变成仪式召唤的怪兽的攻击力以上为止，把自己的手卡·场上的机械族怪兽解放，从自己的手卡·墓地把1只仪式怪兽仪式召唤。 ②：这张卡在墓地存在的场合，以自己场上1只「龙辉巧」怪兽为对象才能发动。那只怪兽的攻击力直到对方回合结束时下降1000，这张卡加入手卡。'),
(30086349, 'Meteor Black Comet Dragon', '凶星龙 陨星黑龙', '流星竜メテオ・ブラック・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 3500, 2000, '7星「真红眼」怪兽＋6星龙族怪兽 ①：这张卡融合召唤的场合才能发动。从手卡·卡组把1只「真红眼」怪兽送去墓地，给与对方那只怪兽的攻击力一半数值的伤害。 ②：这张卡从怪兽区域送去墓地的场合，以自己墓地1只通常怪兽为对象才能发动。那只怪兽特殊召唤。'),
(90660762, 'Meteor Black Dragon', '陨星黑龙', 'メテオ・ブラック・ドラゴン', 'Fusion Monster', 'Dragon', 'FIRE', 8, 3500, 2000, '「真红眼黑龙」＋「流星之龙」'),
(64271667, 'Meteor Dragon', '陨星龙', 'メテオ・ドラゴン', 'Normal Monster', 'Dragon', 'EARTH', 6, 1800, 2000, '从宇宙尽头坠落地球的流星之龙。'),
(17871506, 'Meteor Dragon Red-Eyes Impact', '真红眼凶星龙－陨星龙', '真紅眼の凶星竜－メテオ・ドラゴン', 'Gemini Monster', 'Dragon', 'DARK', 6, 1800, 2000, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●只要这张卡在怪兽区域存在，这张卡以外的自己场上的「真红眼」怪兽不会被战斗·效果破坏。'),
(56856951, 'Meteor Flare', '流星日珥', 'メテオ・プロミネンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方基本分比3000高的场合，把2张手卡送去墓地才能发动。给与对方基本分2000分伤害。这张卡在墓地存在的场合，可以作为自己的抽卡阶段时进行通常抽卡的代替，把这张卡加入手卡。'),
(33767325, 'Meteor of Destruction', '死亡流星', 'デス・メテオ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '给与对方基本分1000分伤害。对方基本分是3000以下的场合这张卡不能发动。'),
(99748883, 'Meteor Rush - Monochroid', '流星连打－黑白机人', '流星連打－シロクロイド', 'Effect Monster', 'Machine', 'EARTH', 10, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：5次以上攻击宣言过的回合的战斗阶段才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：这张卡进行战斗的伤害步骤内，这张卡的攻击力上升这个回合由回合玩家攻击宣言的次数×1000。'),
(64274292, 'Meteorain', '流星雨', 'メテオ・レイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合自己怪兽攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方那个数值的战斗伤害。'),
(24166324, 'Meteoroa Drytron', '极辉龙机巧降星', '流星極輝巧群', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：「龙辉巧」卡被除外的场合，把自己场上1只「龙辉巧」怪兽解放，以自己的除外状态的最多2张「龙辉巧」卡为对象才能发动。那些卡加入手卡。 ②：把手卡1张「流星辉巧群」给对方观看才能发动。攻击力合计直到变成仪式召唤的怪兽的攻击力以上为止，把自己的手卡·场上的机械族怪兽解放，从自己的手卡·墓地把1只机械族仪式怪兽仪式召唤。'),
(26638543, 'Metrognome', '节拍器地精灵', 'メトロンノーム', 'Pendulum Effect Monster', 'Fairy', 'EARTH', 4, 1800, 1600, '①：自己的灵摆区域有2张卡存在，那些灵摆刻度相同的场合，这张卡的攻击力·守备力上升那个灵摆刻度×100，这张卡可以直接攻击。 ②：这张卡直接攻击给与对方战斗伤害的场合发动。双方的灵摆区域的卡全部破坏。'),
(92826944, 'Mezuki', '马头鬼', '馬頭鬼', 'Effect Monster', 'Zombie', 'EARTH', 4, 1700, 800, '①：把墓地的这张卡除外，以自己墓地1只不死族怪兽为对象才能发动。那只不死族怪兽特殊召唤。'),
(30373970, 'Miasma Dragon Tistina', '结瘴龙 提斯蒂娜', '結瘴龍ティスティナ', 'Effect Monster', 'Aqua', 'DARK', 10, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「结瘴龙 提斯蒂娜」以外的1只「提斯蒂娜」怪兽加入手卡。这个回合中，自己场上的光属性「提斯蒂娜」怪兽的攻击力上升1000。 ②：这张卡被送去墓地的场合，若场地区域有卡存在则能发动。这张卡特殊召唤。这个回合，自己不是「提斯蒂娜」怪兽不能从手卡·墓地特殊召唤。'),
(69176851, 'Miasma Necromancer', '瘴烟的死灵术师', '瘴煙の死霊術師', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1800, NULL, '包含魔法师族·暗属性怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己墓地把1只5星以上的魔法师族·暗属性怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡的效果发动。 ②：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。进行1只魔法师族怪兽的召唤。'),
(4779823, 'Michael, the Arch-Lightsworn', '光道大天使 米迦勒', 'ライトロード・アーク ミカエル', 'Synchro Monster', 'Dragon', 'LIGHT', 7, 2600, 2000, '调整＋调整以外的光属性怪兽1只以上 ①：1回合1次，支付1000基本分，以场上1张卡为对象才能发动。那张卡除外。 ②：这张卡被破坏时，以这张卡以外的自己墓地的「光道」怪兽任意数量为对象才能发动。那些怪兽回到卡组，自己回复回去数量×300基本分。 ③：自己结束阶段发动。从自己卡组上面把3张卡送去墓地。'),
(7733560, 'Michion, the Timelord', '时械神 米奇恩', '時械神ミチオン', 'Effect Monster', 'Fairy', 'FIRE', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。对方基本分变成一半。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(37580756, 'Michizure', '同路人', '道連れ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：怪兽被战斗破坏送去自己墓地时或者场上的怪兽被送去自己墓地时，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(2347477, 'Micro Coder', '微代码者', 'マイクロ・コーダー', 'Effect Monster', 'Cyberse', 'DARK', 1, 300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「码语者」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡作为「码语者」怪兽的连接素材从手卡·场上送去墓地的场合才能发动。从卡组把1张「电脑网」魔法·陷阱卡加入手卡。场上的这张卡为素材的场合可以把那1张改成1只电子界族·4星怪兽。'),
(18190572, 'Micro Ray', '微缩光线', 'ミクロ光線', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '使场上1张表侧表示怪兽的守备力变成零直到结束阶段终了时为止。'),
(75487237, 'Mid Shield Gardna', '中型盾守卫者', 'ミドル・シールド・ガードナー', 'Effect Monster', 'Warrior', 'EARTH', 4, 100, 1800, '这张卡1个回合1次可以变成里侧守备表示。以里侧表示的这只怪兽为对象的魔法卡的发动无效。那个时候，这张卡变成表侧守备表示。'),
(300302036, 'Middle Age Mechs (Skill Card)', NULL, NULL, 'Skill Card', 'Dr. Vellian C', NULL, NULL, NULL, NULL, NULL),
(83678433, 'Midnight Fiend', '午夜恶魔', 'ミッドナイト・デビル', 'Normal Monster', 'Fiend', 'DARK', 2, 800, 600, '出现在深夜的鸟怪。据说必须祭生才能唤它出来。'),
(81743801, 'Mighty Dino King Rex', '龙王 恐龙王', '竜王キング・レックス', 'Effect Monster', 'Dinosaur', 'EARTH', 9, 3200, 1200, '①：这张卡的攻击破坏对方怪兽时才能发动。这次战斗阶段中，这张卡只再1次可以攻击。 ②：这张卡在这个回合没有召唤·反转召唤·特殊召唤的场合，1回合1次，以对方场上最多2只怪兽为对象才能发动。那些怪兽破坏。'),
(62327910, 'Mighty Guard', '强力守卫', 'マイティガード', 'Normal Monster', 'Machine', 'EARTH', 4, 500, 1200, '警卫用开发的机械战士。全身采用不锈钢金属制造。'),
(53981499, 'Mighty Warrior', '强劲战士', 'マイティ・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2200, 2000, '调整＋调整以外的怪兽1只以上 这张卡战斗破坏对方怪兽的场合，给与对方基本分破坏的怪兽的攻击力一半数值的伤害。'),
(57736667, 'Mikanko Dance - Mayowashidori', '御巫舞踊－迷乱之鸟', '御巫舞踊－迷わし鳥', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：装备怪兽不会被效果破坏。 ②：自己的「御巫」怪兽进行战斗的伤害步骤结束时，以场上1张卡为对象才能发动。那张卡回到手卡。 ③：这张卡在墓地存在的场合，以自己墓地1只「御巫」怪兽为对象才能发动。那只怪兽特殊召唤，把这张卡装备。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(84550369, 'Mikanko Divine Dance - Futahashira no Uzu no Miko', '御巫神舞－二贵子', '御巫神舞－二貴子', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把「御巫神舞-二贵子」以外的1张「御巫」卡送去墓地。那之后，可以从卡组把「御巫神舞-二贵子」以外的1张「御巫」魔法·陷阱卡在自己场上盖放。这张卡的发动后，直到回合结束时自己不是「御巫」怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外，把自己场上1个超量素材取除才能发动。从手卡·卡组把1只「御巫」仪式怪兽特殊召唤。'),
(80044027, 'Mikanko Fire Dance', '御巫之火丛舞', '御巫の火叢舞', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地把1只「御巫」怪兽特殊召唤，把这张卡装备。那之后，可以从对方墓地把1只怪兽效果无效在对方场上特殊召唤。 ②：装备怪兽不会被效果破坏。'),
(16310544, 'Mikanko Kagura', '御巫神乐', '御巫神楽', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「御巫」仪式怪兽仪式召唤。那之后，以下效果可以适用。 ●把最多有自己墓地的装备魔法卡种类数量的对方场上的卡破坏，给与对方破坏数量×1000伤害。'),
(42705243, 'Mikanko Promise', '御巫之契', '御巫の契り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只「御巫」怪兽特殊召唤。那之后，可以把1张那只怪兽可以装备的装备魔法卡从自己的手卡·墓地给那只怪兽装备。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(16433136, 'Mikanko Purification Dance', '御巫之祓舞', '御巫の祓舞', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「御巫」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽不会被效果破坏。 ②：对方场上有怪兽特殊召唤的场合，以自己以及对方场上的怪兽各1只为对象才能发动。那些怪兽回到手卡。'),
(79912449, 'Mikanko Reflection Rondo', '御巫之幻惑轮舞', '御巫の誘い輪舞', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '可以给对方场上的怪兽装备。这个卡名的卡在1回合只能发动1张。 ①：「御巫的诱轮舞」在自己场上只能有1张表侧表示存在。 ②：只要自己场上有「御巫」怪兽存在，得到装备怪兽的控制权。 ③：装备怪兽只要在自己场上存在，不能把效果发动。 ④：这张卡从场上离开时装备怪兽送去墓地。'),
(78199891, 'Mikanko Rivalry', '御巫神比', '御巫かみくらべ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「御巫」怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。把1张那只怪兽可以装备的装备魔法卡从卡组给那只怪兽装备。 ②：这张卡在墓地存在的状态，装备魔法卡被送去自己墓地的场合，把这张卡除外，以自己墓地1张装备魔法卡为对象才能发动。那张卡加入手卡。'),
(53174748, 'Mikanko Spiritwalk', '御巫神隐', '御巫かみかくし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽给自己场上1只「御巫」怪兽当作装备魔法卡使用来装备。场上有仪式怪兽卡存在的场合，可以再给与对方为自己场上的装备魔法卡数量×500伤害。 ②：把墓地的这张卡除外才能发动。自己的手卡·除外状态的1只「御巫」怪兽特殊召唤。'),
(43527730, 'Mikanko Water Arabesque', '御巫之展翅水舞', '御巫の水舞踏', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽不会被效果破坏。 ②：自己主要阶段才能发动。原本卡名和装备怪兽不同的1只「御巫」怪兽从手卡·卡组特殊召唤，这张卡给那只怪兽装备。那之后，这张卡装备过的怪兽回到手卡。'),
(38277918, 'Mikazukinoyaiba', '新月龙', 'クレセント・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 7, 2200, 2350, '据说来自月亮，手持新月状之刀的龙战士。'),
(85753549, 'Mikazukinoyaiba, the Moon Fang Dragon', '月牙龙－新月龙', '月牙龍－クレセント・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2200, 2350, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，自己·对方的结束阶段才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到卡组最下面。 ②：丢弃1张手卡才能发动。从卡组把1只龙族·暗属性·7星怪兽加入手卡。'),
(47558785, 'Mild Turkey', '温火鸡', 'マイルド・ターキー', 'Pendulum Normal Monster', 'Winged Beast', 'FIRE', 4, 1000, 2000, '对保龄球的热情烤焦全身的狂放火鸡。为了拿到全中而锻炼出来的身体，经常散发出极品的香味。以还没见到的火鸡球作为目标，每天不间断地练习着。'),
(33225925, 'Milla the Temporal Magician', '久远之魔术师 米拉', '久遠の魔術師ミラ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 1000, '①：这张卡召唤成功的场合，以对方场上1张里侧表示的卡为对象发动。把那张对方的卡确认。对方不能对应这个效果的发动把魔法·陷阱卡发动。'),
(37613663, 'Millennium Ankh', '仟年十字', '千年の十字', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己的手卡·卡组·场上（表侧表示）5张「被封印」怪兽卡，给双方确认。那之后，从额外卡组把1只「幻之召唤神 艾克佐迪亚」特殊召唤。除「千年」怪兽卡、原本等级是10星以上的「艾克佐迪亚」怪兽卡外的表侧表示的怪兽卡在自己场上存在的场合，再让那些全部回到卡组。这个回合，自己不能把怪兽召唤·反转召唤·特殊召唤。发动后这张卡不送去墓地，回到卡组。'),
(300201009, 'Millennium Eye (Skill Card)', NULL, NULL, 'Skill Card', 'Pegasus', NULL, NULL, NULL, NULL, NULL),
(47986555, 'Millennium Golem', '仟年魔像', '千年ゴーレム', 'Normal Monster', 'Rock', 'EARTH', 6, 2000, 2200, '千年间一直在守护着王家财宝的石像。'),
(300201006, 'Millennium Necklace (Skill Card)', NULL, NULL, 'Skill Card', 'Ishizu', NULL, NULL, NULL, NULL, NULL),
(41044418, 'Millennium Revelation', '千年的启示', '千年の啓示', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只幻神兽族怪兽送去墓地才能发动。从自己的卡组·墓地选1张「死者苏生」加入手卡。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。这个回合，可以用自己的「死者苏生」把自己墓地的「太阳神之翼神龙」无视召唤条件特殊召唤。这个效果发动的回合的结束阶段，自己必须把「死者苏生」的效果特殊召唤的「太阳神之翼神龙」送去墓地。'),
(82482194, 'Millennium Scorpion', '千年蝎', 'ミレニアム・スコーピオン', 'Effect Monster', 'Insect', 'EARTH', 5, 2000, 1800, '每次这张卡战斗破坏对方场上1只怪兽送去墓地的场合，这张卡攻击力上升500。'),
(5130393, 'Millennium Seeker', '千年血族', '千年の血族', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己因战斗·效果受到1000以上的伤害时才能发动。这张卡从手卡特殊召唤。 ②：以对方墓地1只攻击力是?以外的怪兽为对象才能发动。对方可以从卡组选1只攻击力是?以外的怪兽。没选的场合或者作为对象的怪兽攻击力更高的场合，作为对象的怪兽在自己场上特殊召唤。选的怪兽回到卡组。那以外的场合，对方把选的怪兽加入手卡。'),
(32012841, 'Millennium Shield', '仟年之盾', '千年の盾', 'Normal Monster', 'Warrior', 'EARTH', 5, NULL, 3000, '据说是从古埃及王家传下来的传说之盾。传闻说再怎么强的攻击也能防住。'),
(89785779, 'Millennium-Eyes Illusionist', '千年眼幻象师', 'ミレニアム・アイズ・イリュージョニスト', 'Effect Monster', 'Spellcaster', 'DARK', 2, NULL, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以对方场上1只效果怪兽为对象才能发动。选自己场上1只「眼纳祭神」融合怪兽或者「纳祭之魔」把作为对象的对方的效果怪兽当作那个效果的装备卡使用来装备。这个效果在对方回合也能发动。 ②：场上有「眼纳祭神」融合怪兽或者「纳祭之魔」特殊召唤的场合发动。墓地的这张卡加入手卡。'),
(41578483, 'Millennium-Eyes Restrict', '千年眼纳祭魔', 'ミレニアム・アイズ・サクリファイス', 'Fusion Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '「纳祭之魔」＋效果怪兽 ①：1回合1次，对方怪兽的效果发动时，以对方的场上·墓地1只效果怪兽为对象才能发动。那只对方的效果怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力·守备力上升这张卡的效果装备的怪兽的各自数值。 ③：原本卡名和这张卡的效果装备的怪兽相同的怪兽不能攻击，那个效果无效化。'),
(23746827, 'Million-Century Ice Prison', '亿年之冰墓', '億年の氷墓', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，对方怪兽的效果用除破坏以外的方法让自己场上的怪兽从场上离开的场合，可以从以下效果选择1个发动。 ●这次主要阶段结束。 ●下次的对方回合的主要阶段1跳过。'),
(7489323, 'Milus Radiant', '金毛犼', 'ミリス・レディエント', 'Effect Monster', 'Beast', 'EARTH', 1, 300, 250, '只要这张卡在场上表侧表示存在，全部地属性的怪兽攻击力上升500。风属性的怪兽攻击力下降400。'),
(10632284, 'Mimesis Elephant', '拟态象', 'ミメシスエレファント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡发动后变成效果怪兽（兽族·地·2星·攻0/守2000）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ②：这张卡在怪兽区域存在的场合，自己·对方回合，宣言种族和属性各1个，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时变成宣言的种族·属性。'),
(88032456, 'Mimicat', '复制猫', 'コピーキャット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「复制猫」在1回合只能发动1张。 ①：自己场上有「卡通世界」以及卡通怪兽存在的场合，以对方墓地1张卡为对象才能发动。那张卡是怪兽的场合，那只怪兽在自己场上特殊召唤。那张卡是魔法·陷阱卡的场合，那张卡在自己场上盖放。'),
(72427512, 'Mimicking Man-Eater Bug', '拟态的食人虫', '擬態する人喰い虫', 'Flip Effect Monster', 'Insect', 'EARTH', 4, 450, 600, '①：这张卡反转的场合，以场上1只怪兽为对象发动。那只怪兽破坏，这张卡的攻击力上升那个原本攻击力数值。那之后，可以把这张卡的种族变成和破坏的怪兽的原本种族相同。 ②：场上的这张卡不会被战斗破坏，也不会被和这张卡相同种族的怪兽的效果破坏。'),
(5972394, 'Mimiclay', '模仿黏土', 'モノマネンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「模仿黏土」在1回合只能发动1张。 ①：对方场上有怪兽存在的场合，以自己场上1只2星以下的表侧守备表示怪兽为对象才能发动。那1只同名怪兽从卡组守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(50415441, 'Mimighoul Archfiend', '迷拟宝箱鬼・恶魔', 'ミミグル・デーモン', 'Flip Effect Monster', 'Fiend', 'EARTH', 1, NULL, 1900, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。场上1只里侧表示怪兽变成表侧攻击表示或表侧守备表示。 ③：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●对方抽1张。 ●选自己1张手卡送去墓地。 ●这张卡的控制权移给对方。'),
(11677278, 'Mimighoul Armor', '迷拟宝箱鬼・铠甲', 'ミミグル・アーマー', 'Flip Effect Monster', 'Warrior', 'EARTH', 1, 600, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。对方场上有怪兽存在的场合，也能作为代替在自己场上表侧表示特殊召唤。 ②：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●这个回合中，「迷拟宝箱鬼」怪兽不会被战斗破坏。 ●这张卡的控制权移给对方。'),
(23920796, 'Mimighoul Cerberus', '迷拟宝箱鬼・三头犬', 'ミミグル・ケルベロス', 'Flip Effect Monster', 'Beast', 'EARTH', 1, 400, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。 ②：对方不能把自己场上的表侧表示的魔法卡作为效果的对象。 ③：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●从自己卡组上面把3张卡除外。那之后，自己的除外状态的1只怪兽在对方场上守备表示特殊召唤。 ●这张卡的控制权移给对方。'),
(55733143, 'Mimighoul Charm', '迷拟宝箱鬼・魅惑', 'ミミグル・チャーム', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合可以使用最多2次。 ①：对方场上的「迷拟宝箱鬼」怪兽在主要阶段反转的场合才能发动（同一连锁上最多1次）。对方的额外卡组的里侧的卡随机选1张。那张卡是可以特殊召唤的怪兽的场合，那只怪兽在自己场上特殊召唤。不是的场合或者不能特殊召唤的场合，那张卡除外。这个效果特殊召唤的怪兽在这个回合不能把效果发动。'),
(81522098, 'Mimighoul Dragon', '迷拟宝箱鬼・火龙', 'ミミグル・ドラゴン', 'Flip Effect Monster', 'Dragon', 'EARTH', 1, 500, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「迷拟宝箱鬼」魔法·陷阱卡加入手卡。 ③：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●「迷拟宝箱鬼」怪兽以外的自己场上的表侧表示怪兽全部破坏。 ●这张卡的控制权移给对方。'),
(86809440, 'Mimighoul Dungeon', '迷拟宝箱鬼・地下城', 'ミミグル・ダンジョン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这个回合没有召唤·特殊召唤的自己场上的「迷拟宝箱鬼」怪兽的攻击力上升自身的原本守备力数值。 ②：双方各自只要自身场上有里侧表示怪兽存在，不能把怪兽召唤，不能用这个回合特殊召唤的怪兽攻击宣言。 ③：自己主要阶段才能发动。从自己的卡组·墓地把1只「迷拟宝箱鬼」怪兽加入手卡。'),
(43066927, 'Mimighoul Fairy', '迷拟宝箱鬼・妖精', 'ミミグル・フェアリー', 'Flip Effect Monster', 'Fairy', 'EARTH', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。自己场上有「迷拟宝箱鬼」怪兽存在的场合，也能作为代替在自己场上表侧表示特殊召唤。 ②：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●这个回合，自己不能把从自身手卡特殊召唤的怪兽的效果发动。 ●这张卡的控制权移给对方。');